WITH exploded AS (SELECT id, host, log_ts, level, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, attr_value), parsed AS (SELECT log_ts, level, status_code, k, CAST((status_code & 4) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded), kept_keys AS (SELECT level FROM parsed INTERSECT SELECT level FROM app_logs WHERE HOUR(log_ts) BETWEEN 12 AND 17), verified AS (SELECT s.* FROM parsed s INNER JOIN kept_keys k ON s.level = k.level), valid AS (SELECT level, k, has_fault, status_code_high, CONCAT_WS('/', level, k) AS level_k_key FROM verified WHERE k IS NOT NULL) SELECT k, has_fault, status_code_high FROM valid ORDER BY has_fault DESC, k;
